  Definition aapp_lo (A n : Z) : Prop := AIMG_TOP <= A /\ A + n <= ALOWSH_LO.
  Definition aapp_hi (A n : Z) : Prop := AHI_LO <= A /\ A + n <= aceil.
  Definition aapp (A n : Z) : Prop := aapp_lo A n \/ aapp_hi A n.

