(* [comment removed for export] *)
Ltac acb :=
  let K := fresh "ACEILB" in
  pose proof (aceil_facts : 0x7fff7f800000 <= aceil <= 0x7fffff800000 /\ aceil mod 4096 = 0 /\ aceil <= hceil < aceil + 4096) as K.
